use std::collections::HashMap;
use std::env;
use std::sync::{LazyLock, OnceLock};

// A global static whose value is computed at runtime on first use.
//
// `static` items normally require const-evaluable initializers. `LazyLock`
// lifts that restriction: the closure runs exactly once, on first deref,
// and every later access reuses the cached value.
static HTTP_STATUS_CODES: LazyLock<HashMap<u16, &'static str>> = LazyLock::new(|| {
    println!("initializing HTTP_STATUS_CODES (runs once)");
    let mut map = HashMap::new();
    for (code, reason) in [
        (200u16, "OK"),
        (301, "Moved Permanently"),
        (404, "Not Found"),
        (500, "Internal Server Error"),
    ] {
        map.insert(code, reason);
    }
    map
});

// When initialization can fail, or needs runtime input, use `OnceLock` with
// a fallible initializer and `get_or_init`/`get_or_try_init` style handling.
static WORKER_THREADS: OnceLock<usize> = OnceLock::new();

fn worker_threads() -> usize {
    *WORKER_THREADS.get_or_init(|| {
        env::var("WORKER_THREADS")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or_else(|| {
                std::thread::available_parallelism()
                    .map(|n| n.get())
                    .unwrap_or(1)
            })
    })
}

fn main() {
    // Both accesses share a single initialization.
    println!("{}", HTTP_STATUS_CODES.get(&200).unwrap());
    println!("{}", HTTP_STATUS_CODES.get(&404).unwrap());

    println!("worker threads: {}", worker_threads());
    println!("worker threads: {}", worker_threads());
}

