mod tests {
    use super::*;

    #[test]
    fn table_is_populated() {
        assert_eq!(HTTP_STATUS_CODES.get(&500), Some(&"Internal Server Error"));
    }

    #[test]
    fn threads_default_to_at_least_one() {
        assert!(worker_threads() >= 1);
    }
}
